let items=structuredClone(initial),dbp,libp,doc=null,loadTask=null,active=null,spread=0,epoch=0,busy=false,selected='',coverFile=null,pdfFile=null,uploading=false,back=false;
const urls=new Map();
function database(){return dbp ||= new Promise((ok,no)=>{const r=indexedDB.open('mgd-publications',1);r.onupgradeneeded=()=>r.result.createObjectStore('assets');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
async function store(k,v){const d=await database();return new Promise((ok,no)=>{const t=d.transaction('assets',v===undefined?'readonly':'readwrite'),r=v===undefined?t.objectStore('assets').get(k):t.objectStore('assets').put(v,k);t.oncomplete=()=>ok(r.result);t.onerror=()=>no(t.error);t.onabort=()=>no(t.error)})}
async function url(k){if(!k)return '';if(k.startsWith('local:')){if(urls.has(k))return urls.get(k);const b=await store(k);if(!b)throw Error('Dosya bu tarayıcıda bulunamadı.');const u=URL.createObjectURL(b);urls.set(k,u);return u}if(/^assets\/[\w/.-]+$/.test(k)||/^https:\/\//.test(k))return k;throw Error('Geçersiz dosya yolu.')}
