function dialog(id,cls,body){const d=document.createElement('dialog');d.id=id;d.className='pub-dialog '+cls;d.innerHTML=body;document.body.append(d);d.querySelector('.pub-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()});return d}
