const catalog=dialog('pub-catalog','pub-catalog',header('MİLLÎ GENÇLİK KÜTÜPHANESİ','Yayınlarımız')+'<div class="pub-tools"><input id="pub-search" type="search" placeholder="Yayın ara…" aria-label="Yayın ara"><select id="pub-filter" aria-label="Tür"><option>Tümü</option><option>Konseptler</option><option>Broşür ve Pankartlar</option><option>Yayınlarımız</option><option>Kurumsal Kimlik</option></select></div><div id="pub-grid"></div>');
